@prefix aegis: <http://aegis.gastown.local/ontology/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix stable_1: <https://w3id.org/intigraph/camayoc/core/ns#> .
@prefix stable_9: <https://w3id.org/intigraph/quipu/ns#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

stable_1:MemoryDecisionShape a sh:NodeShape ;
    sh:message "A memory Decision needs --chose, --decided-by, --about and --topic, each exactly once. Run the cy create tool with --help for each field." ;
    sh:or ( [ sh:not [ sh:or ( [ sh:class stable_9:Decision ] [ sh:class aegis:Decision ] ) ] ] [ sh:node stable_1:MemoryDecisionBodyShape ] ) ;
    sh:targetSubjectsOf aegis:naturalKey,
        stable_1:naturalKey .

stable_1:MemoryDecisionBodyShape a sh:NodeShape ;
    sh:property [ sh:description "Who ruled: a Person or agent entity (IRI or local name)." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: a decision needs who ruled (--by), as an existing person or agent." ;
            sh:minCount 1 ;
            sh:name "by" ;
            sh:nodeKind sh:IRI ;
            sh:order 2 ;
            sh:path [ sh:alternativePath ( stable_1:decidedBy aegis:decidedBy ) ] ],
        [ sh:datatype xsd:string ;
            sh:description "What was chosen, in one sentence." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: a decision needs what was chosen (--chose)." ;
            sh:minCount 1 ;
            sh:name "chose" ;
            sh:order 1 ;
            sh:path [ sh:alternativePath ( stable_1:chose aegis:chose ) ] ],
        [ sh:datatype xsd:string ;
            sh:description "Why, in one or two sentences." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: give one --rationale." ;
            sh:name "rationale" ;
            sh:order 6 ;
            sh:path [ sh:alternativePath ( stable_1:rationale aegis:rationale ) ] ],
        [ sh:datatype xsd:string ;
            sh:description "An alternative that was not chosen; repeat for each." ;
            sh:message "Not recorded: --over is plain text, one alternative per flag." ;
            sh:name "over" ;
            sh:order 5 ;
            sh:path [ sh:alternativePath ( stable_1:over aegis:over ) ] ],
        [ sh:description "The registered memory topic the decision answers (cy topic add registers one)." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: a decision needs a registered topic (--topic)." ;
            sh:minCount 1 ;
            sh:name "topic" ;
            sh:nodeKind sh:IRI ;
            sh:order 4 ;
            sh:path [ sh:alternativePath ( stable_1:topic aegis:topic ) ] ],
        [ sh:description "The board item or session the decision was made in (IRI or local name)." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: --decided-in names one board item or session." ;
            sh:name "decidedIn" ;
            sh:nodeKind sh:IRI ;
            sh:order 7 ;
            sh:path [ sh:alternativePath ( stable_1:decidedIn aegis:decidedIn ) ] ],
        [ sh:datatype xsd:string ;
            sh:description "The ruling in the decider's own words." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: give one --verbatim quote." ;
            sh:name "verbatim" ;
            sh:order 8 ;
            sh:path [ sh:alternativePath ( stable_1:verbatim aegis:verbatim ) ] ],
        [ sh:description "The entity the decision is about: host, repo, service, role, agent or person (IRI or local name)." ;
            sh:maxCount 1 ;
            sh:message "Not recorded: a decision needs what it is about (--about), as an existing entity." ;
            sh:minCount 1 ;
            sh:name "about" ;
            sh:nodeKind sh:IRI ;
            sh:order 3 ;
            sh:path [ sh:alternativePath ( stable_1:about aegis:about ) ] ] .
